/* fault_kernel.c — CHAOSROB exc_suppress verification kernel.
 *
 * Produces a REPRODUCIBLE architectural fault (data abort via a deliberate
 * NULL-pointer deref guarded so it doesn't segfault the host). Without
 * injection: the faulting load traps -> Crash (DUE). With CHAOSROB
 * exc_suppress: the faulting DynInst's `fault` is cleared -> the load
 * completes with garbage -> SDC (no trap, wrong result).
 *
 * Output: 16-hex checksum of the result vector (stdout) + iters/fails (stderr).
 * The "golden" is the no-fault path: when the guarded load is allowed to
 * fault-and-recover (returns 0), the checksum is deterministic. exc_suppress
 * changes the faulting load's outcome -> different checksum -> SDC.
 *
 * Compile: gcc -static -O2 -o fault_kernel fault_kernel.c
 */
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

/* A "faulting" load guarded by a sentinel. We use a low-address read that
 * gem5 SE will trap as a Data Abort (addr 0 is unmapped in SE). The kernel
 * computes over a result array and folds one element from a "faulting" read
 * (addr chosen to abort). exc_suppress clears the fault -> the read returns
 * whatever garbage -> result differs -> SDC. */
static uint64_t faulting_load(void *addr) {
    /* volatile so the read isn't optimized away */
    volatile uint64_t *p = (volatile uint64_t *)addr;
    return *p;
}

int main(int argc, char **argv) {
    long iters = (argc > 1) ? atol(argv[1]) : 100;
    uint64_t result = 0x1234567890abcdefULL;  /* base */
    uint64_t acc = 0;
    for (long it = 0; it < iters; it++) {
        /* a normal computation */
        acc += result * (uint64_t)(it + 1);
        /* a "faulting" load: addr 0 is unmapped in gem5 SE -> Data Abort.
         * Guarded: we never actually deref NULL on the host (the function
         * is called but gem5 traps before the host sees it). On native this
         * WOULD segfault — so guard with a no-fault path for native golden. */
        void *fault_addr = (void *)0;  /* unmapped in gem5 SE */
        /* only attempt the faulting load in gem5 (where it traps); on native
         * we skip it. We detect "gem5" via a known env quirk: gem5 SE reports
         * /proc/self/exe via readlink (see arm_chaos.py warn). Simple: a
         * compile-time guard — native golden never calls faulting_load. */
#ifdef GEM5_BUILD
        uint64_t fv = faulting_load(fault_addr);
        acc += fv;  /* this traps in gem5 unless exc_suppress clears it */
#else
        /* native: no faulting load; acc stays deterministic */
        (void)fault_addr;
#endif
    }
    uint64_t checksum = acc ^ 0xCAFEBABEDEADBEEFULL;
    printf("%016lx\n", checksum & 0xFFFFFFFFFFFFFFFFULL);
    fprintf(stderr, "iters=%ld fails=0 variant=fault_kernel\n", iters);
    return 0;
}

